```c++:createTiff.cpp
// g++ main_createTiff.cpp -o createTiff `pkg-config libtiff-4 --cflags --libs`

#include <tiffio.h>
#include <cstring>

int main( void )
{
    const int bmp_ncn    = 3;
    const int bmp_bpp    = 48;
    const int bmp_width  = 32768;
    const int bmp_height = 5462; // 5461 is OK, 5462 is NG.

    /**
     * 32768 x 5461 x 3ch x 2byte = 1,073,676,288.
     * 1024 * 1024 * 1024         = 1,073,741,824.
     * 32768 x 5462 x 3ch x 2byte = 1,073,872,896.
     */
    TIFF* tif = TIFFOpen("output.tif", "w");
    TIFFSetField(tif, TIFFTAG_COMPRESSION, COMPRESSION_LZW);
    TIFFSetField(tif, TIFFTAG_IMAGEWIDTH,  bmp_width);
    TIFFSetField(tif, TIFFTAG_IMAGELENGTH, bmp_height);
    TIFFSetField(tif, TIFFTAG_BITSPERSAMPLE, bmp_bpp / bmp_ncn);
    TIFFSetField(tif, TIFFTAG_SAMPLESPERPIXEL, bmp_ncn);
    TIFFSetField(tif, TIFFTAG_PHOTOMETRIC, PHOTOMETRIC_RGB);
    TIFFSetField(tif, TIFFTAG_PLANARCONFIG, PLANARCONFIG_CONTIG);
    TIFFSetField(tif, TIFFTAG_FILLORDER, FILLORDER_MSB2LSB);
    TIFFSetField(tif, TIFFTAG_ROWSPERSTRIP, bmp_height );

    char* line_buf = new char [ bmp_width * ( bmp_bpp / 8 ) ];
    memset ( line_buf, 0 , sizeof line_buf );
    for ( int row = 0 ; row < bmp_height ; row++ )
    {
        TIFFWriteScanline(tif, line_buf, row );
    }
    TIFFClose(tif);

    delete []line_buf;
    return 0;
}
